                const ls = S2.scr.get(m); if (ls == null || g.t - ls > 0.12) { S2.scr.set(m, g.t); scratch(m.x, m.y, f.rot, col); X.sparks(m.x, m.y - 0.4, '#FFFFFF', 3, 4); }
